-- Generated by scripts/sync_chat.py; edit shared/chat_ui.lua.
local transport,application_name="esp_now","esp_chat"
-- Source of the three downloadable chat interfaces. Transport/storage stays in
-- the firmware service; navigation, composition, bubbles and labels are Lua.
local view,peer,identity="home","",""
local contacts,messages,nearby={},{},{}
local state,revision,add_result="stopped",-1,0
local running,background=false,false
local page,older,drawn=0,0,1
local error_text,input_kind="",""
local selected_message=nil
local statuses={stopped={"Stopped","未连接"},starting={"Starting…","正在启动…"},online={"Connected","已连接"},connecting={"Connecting…","正在连接…"},failed={"Connection failed","连接失败"},storage_error={"Storage error","存储错误"}}
local deliveries={{"Received","已收到"},{"Sending…","发送中…"},{"Broadcast sent","广播已发送"},{"Delivered","已送达"},{"Failed · tap to retry","失败 · 点击重试"}}
local outcomes={{"",""},{"Processing…","处理中…"},{"Request sent; waiting for acceptance","已发送请求，等待对方接受"},{"Friend added","已添加好友"},{"Already a friend","已经是好友"},{"Invalid ID","ID 格式错误"},{"Contact limit reached","好友数量已满"},{"Storage error","存储错误"},{"Request failed","请求失败"}}
local function tr(pair) return app.tr(pair[1],pair[2]) end
local function short(id) return #id>16 and id:sub(1,8).."…"..id:sub(-6) or id end
local function peer_name(id) return id=="*" and app.tr("Public chat","公共聊天") or short(id) end
local function online(id)
  for _,contact in ipairs(contacts) do if contact.id==id then return contact.online end end
  return false
end
local function refresh()
  local ok,s,r,n,m,my_id=app.chat("snapshot")
  if not ok then return false end
  local changed=r~=revision or s~=state
  state,revision,identity=s,r,my_id
  if not changed then return false end
  contacts={};messages={};nearby={}
  for i=1,n do local yes,id,on,request=app.chat("contact","",i);if yes then contacts[#contacts+1]={id=id,online=on==1,request=request==1} end end
  for i=1,m do local yes,text,delivery,id,receipts,p=app.chat("message","",i);if yes then messages[#messages+1]={text=text,delivery=delivery,id=id,receipts=receipts,peer=p} end end
  local _,_,count=app.chat("nearby_count")
  if transport=="wifi" then
    for i=1,count do local yes,id=app.chat("nearby","",i);if yes then nearby[#nearby+1]=id end end
  else for _,contact in ipairs(contacts) do if contact.online then nearby[#nearby+1]=contact.id end end end
  local _,_,result=app.chat("add_result");add_result=result
  local _,_,enabled=app.chat("background");background=enabled==1
  return true
end
local function show()
  app.clear();app.title(view=="thread" and peer_name(peer) or application_name);app.canvas()
  local w,h=app.size();local gap=10
  local footer=h-52
  if not running then
    app.text(0,30,w,100,app.tr("Connect and start a conversation","连接后，开始聊天"),2,1)
    local permission=transport=="wifi" and "network" or "radio"
    app.text(0,150,w,110,app.allowed(permission) and app.tr("Open the connection, then discover nearby devices.","启动连接后，可以发现附近设备。") or
      app.tr("Allow communication in Store settings → Application permissions.","请在商店设置的应用权限中允许通信。"),1,1)
    app.button(1,0,footer,w,52,app.tr("Connect","连接"),3);return
  end
  if view=="identity" then
    app.text(0,0,w,46,app.tr("My ID","我的 ID"),2,0)
    if #identity==0 then app.text(0,80,w,100,app.tr("Identity is not ready yet","身份尚未就绪"),1,1)
    else
      local size=math.min(w,h-185);local payload=transport=="wifi" and "tox:"..identity or identity
      app.qr((w-size)/2,58,size,payload)
      app.text(0,66+size,w,48,short(identity),0,1)
    end
    app.button(16,0,footer,w,52,app.tr("Show full ID","显示完整 ID"),0);return
  end
  if view=="full_id" then
    app.text(0,0,w,46,app.tr("One complete ID","一个完整的 ID"),2,0)
    app.text(0,80,w,h-190,identity,1,0)
    app.button(15,0,footer,w,52,app.tr("Show QR code","显示二维码"),0);return
  end
  if view=="invite" then
    app.text(0,0,w,50,app.tr("Friend request","好友请求"),2,0)
    app.text(0,78,w,90,short(peer),1,1)
    app.text(0,190,w,80,app.tr("Accept this device as a friend?","是否接受此设备为好友？"),1,1)
    app.button(17,0,footer,w,52,app.tr("Accept","接受好友请求"),3);return
  end
  if view=="options" then
    app.text(0,0,w,44,app.tr("Discovery and settings","发现与设置"),2,0)
    local controls={{15,app.tr("My ID · QR code","我的 ID · 二维码")},{14,app.tr("Add by ID","通过 ID 添加")},
      {18,background and app.tr("Background listening: on","后台收听：开") or app.tr("Background listening: off","后台收听：关")},
      {11,app.tr("Discover nearby","发现附近设备")}}
    for i,item in ipairs(controls) do app.button(item[1],0,58+(i-1)*66,w,54,item[2],0) end
    app.text(0,330,w,90,app.tr("Background listening works only while the device is awake. It stops during sleep.","仅在设备唤醒时后台收听，休眠期间不接收。"),0,0,6)
    if error_text~="" then app.text(0,h-100,w,80,error_text,0,0) end
    return
  end
  if view=="thread" then
    local status=peer=="*" and tr(statuses[state]) or online(peer) and app.tr("Online","在线") or app.tr("Offline · delivery may fail","未连接 · 可能无法送达")
    app.text(0,0,w,32,error_text~="" and error_text or status,0,0,6)
    for i,label in ipairs({app.tr("Older","更早"),app.tr("Newer","更新"),app.tr("Details","详情")}) do
      app.button(i+19,(i-1)*(w+8)/3,44,(w-16)/3,40,label,0)
    end
    local list={};for i=#messages,1,-1 do if messages[i].peer==peer then list[#list+1]=messages[i] end end
    older=math.min(older,math.max(0,#list-1))
    local bottom=footer-18;drawn=0
    for index=older+1,#list do
      local message=list[index];local outgoing=message.delivery~=0
      local tw,th=app.measure(message.text,w*.78-24,1)
      local bw=math.min(w*.78,math.max(76,tw+24));local bh=math.min(h-230,math.max(48,th+20))
      local caption=outgoing and tr(deliveries[message.delivery+1]) or ""
      if message.receipts>0 then caption=app.tr("Received by ","已被 ")..message.receipts..app.tr(" devices"," 台设备收到") end
      local total=bh+(outgoing and 32 or 0)
      if bottom-total<100 then break end
      local x=outgoing and w-bw or 0;local y=bottom-total
      app.box(x,y,bw,bh,outgoing and 0 or 15,12)
      if not outgoing then app.box(x,y,bw,bh,0,12,1) end
      app.text(x+12,y+10,bw-24,bh-20,message.text,1,0,outgoing and 15 or 0)
      if outgoing then app.text(0,y+bh+3,w,27,caption,0,2,6) end
      app.hit(100+index,0,y,w,total)
      bottom=y-14;drawn=drawn+1
    end
    if #list==0 then app.text(0,110,w,h-220,app.tr("Say hello.","发一句问候吧。"),1,1,6) end
    app.button(19,0,footer,w,52,app.tr("Write a message","编写消息"),3)
    return
  end
  if view=="message" and selected_message then
    app.text(0,0,w,40,app.tr("Message","消息"),2,0)
    app.text(0,62,w,h-160,selected_message.text,1,0)
    app.button(23,0,footer,w,52,app.tr("Return to conversation","返回聊天"),0);return
  end
  if view=="details" then
    app.text(0,0,w,50,peer_name(peer),2,0)
    app.text(0,74,w,h-190,peer=="*" and app.tr("Public messages reach nearby devices listening on the same channel. Broadcast delivery does not guarantee that every device received it.","公共消息发给同频道收听中的附近设备。广播发出不代表所有设备都已收到。") or peer,1,0)
    app.button(23,0,footer,w,52,app.tr("Return to conversation","返回聊天"),0);return
  end
  local discovering=view=="nearby"
  app.text(0,0,w,42,discovering and app.tr("Nearby devices","附近设备") or tr(statuses[state]),2,0)
  local result=outcomes[add_result+1] or outcomes[1]
  app.text(0,44,w,36,error_text~="" and error_text or tr(result),0,0,6)
  local items={}
  if discovering then for _,id in ipairs(nearby) do items[#items+1]={id=id,online=true} end
  else
    if transport~="wifi" then items[#items+1]={id="*",online=state=="online"} end
    for _,contact in ipairs(contacts) do items[#items+1]=contact end
  end
  local per=math.max(1,math.floor((h-165)/76));local start=page*per+1
  if start>#items then page=0;start=1 end
  for j=0,per-1 do
    local item=items[start+j];if not item then break end
    local y=90+j*76
    app.box(0,y,50,54,item.id=="*" and 0 or 12,12)
    app.text(0,y,50,54,item.id=="*" and "#" or item.id:sub(1,2),1,1,item.id=="*" and 15 or 0)
    app.text(64,y,w-64,30,peer_name(item.id),1,0)
    app.text(64,y+33,w-64,25,item.request and app.tr("Tap to accept request","点击接受好友请求") or item.online and app.tr("Online","在线") or app.tr("Offline","未连接"),0,0,6)
    app.hit((discovering and 60 or 30)+start+j,0,y,w,64)
  end
  if #items==0 then app.text(0,100,w,h-220,discovering and app.tr("Keep the other device awake and start discovery there too.","让另一台设备保持唤醒，并打开附近发现。") or app.tr("No conversations yet. Discover a nearby device to begin.","还没有会话，先发现附近设备吧。"),1,1,6) end
  local labels=discovering and {app.tr("Refresh","刷新"),app.tr("Next page","下一页")} or {app.tr("Discover","发现"),app.tr("Settings","设置")}
  app.button(11,0,footer,(w-10)/2,52,labels[1],0)
  app.button(discovering and 24 or 12,(w+10)/2,footer,(w-10)/2,52,labels[2],0)
end
local function start()
  error_text="";running=app.chat("start",transport)
  if running then revision=-1;refresh();if app.context()~="" then peer=app.context();view="thread";app.chat("viewing",peer) end end
  show()
end
return {
  on_start=start,on_resize=show,
  on_network=function(ok) if ok==1 then start() else running=false;show() end end,
  on_tick=function() if running and refresh() then show() end end,
  on_select=function(id)
    error_text=""
    if id==1 then start();return
    elseif id==11 then view="nearby";page=0;app.chat("discover");revision=-1;refresh()
    elseif id==12 then view="options"
    elseif id==14 then input_kind="add";app.input(app.tr("Paste full ID","粘贴完整 ID"),"")
    elseif id==15 then view="identity"
    elseif id==16 then view="full_id"
    elseif id==17 then if not app.chat("add",peer) then error_text=app.tr("Request could not be submitted","请求未能提交") end;view="home";revision=-1;refresh()
    elseif id==18 then
      if not app.chat("background",background and "off" or "on") then error_text=app.tr("Allow background listening in Store settings first.","请先在商店设置中允许后台收听。") end
      revision=-1;refresh()
    elseif id==19 then input_kind="message";app.input(app.tr("Write a message","编写消息"),"")
    elseif id==20 then if drawn>0 then older=older+drawn end
    elseif id==21 then older=math.max(0,older-math.max(1,drawn))
    elseif id==22 then view="details"
    elseif id==23 then view="thread"
    elseif id==24 then page=page+1
    elseif id>=101 then
      local list={};for i=#messages,1,-1 do if messages[i].peer==peer then list[#list+1]=messages[i] end end
      local message=list[id-100]
      if message then
        if message.delivery==4 then
          if not app.chat("retry",peer,message.id) then error_text=app.tr("Could not retry","暂时无法重试") end
        else selected_message=message;view="message" end
      end
    elseif id>=61 then
      peer=nearby[id-60] or "";if peer=="" then return end
      if transport=="wifi" then
        if not app.chat("add",peer) then error_text=app.tr("Request could not be submitted","请求未能提交") end
        view="home"
      else view="thread";older=0;app.chat("viewing",peer) end
    elseif id>=31 then
      local index=id-30
      if transport~="wifi" and index==1 then peer="*";view="thread"
      else
        local contact=contacts[index-(transport~="wifi" and 1 or 0)]
        if not contact then return end
        peer=contact.id;view=contact.request and "invite" or "thread"
      end
      older=0;app.chat("viewing",peer)
    end
    show()
  end,
  on_input=function(_,text)
    if text=="" then return end
    if input_kind=="add" then
      if text:sub(1,4)=="tox:" then text=text:sub(5) end
      if not app.chat("add",text) then error_text=app.tr("Invalid ID or request failed","ID 不正确或请求提交失败") end
      view="home"
    elseif input_kind=="message" then
      if not app.chat("send",peer,0,text) then error_text=app.tr("Not sent. Check the connection and try again.","未发送，请检查连接后重试。") end
      older=0
    end
    revision=-1;refresh();show()
  end,
  on_swipe=function(_,direction)
    if view=="home" or view=="nearby" then
      page=math.max(0,page+((direction=="left" or direction=="up") and 1 or -1));show()
    end
  end,
  on_back=function()
    if view=="home" or not running then app.exit();return end
    if view=="full_id" then view="identity" elseif view=="details" or view=="message" then view="thread" else view="home";page=0;app.chat("viewing","") end
    show()
  end,
}
